 useEffect(()=>{void getAuthSnapshot().then(async a=>{if(a.session){await bootstrapPerson();setAuthenticated(true);await hydrate()}}).catch(()=>setError('No pudimos recuperar tu información. Volvé a intentarlo.')).finally(()=>setAuthReady(true))},[hydrate])
 useEffect(()=>{if(lumiOpen||(!authOpen&&!memoryOpen))return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector<HTMLElement>('.gm-auth[role="dialog"]');const focusables=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),a[href]')||[]);focusables()[0]?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){setAuthOpen(false);setPendingAction(null);setMemoryOpen(false);setMemoryAction(null);setLumiOpen(false)}if(e.key==='Tab'){const nodes=focusables();const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus()}},[authOpen,memoryOpen,otpSent,lumiOpen])
 const requireAuth=(action:()=>Promise<void>)=>{if(!online){setError('Estás sin conexión. Lo escrito sigue acá; reintentá cuando vuelva la red.');return}if(authenticated){void action();return}setPendingAction(()=>action);setAuthOpen(true)}
 const sendOtp=async()=>{setBusy(true);setError('');try{await requestEmailOtp(email);setOtpSent(true)}catch(e){setError(e instanceof Error?e.message:'No pudimos enviar el código')}finally{setBusy(false)}}
 const confirmOtp=async()=>{setBusy(true);setError('');try{const a=await verifyEmailOtp(email,otp);if(!a.session)throw new Error('No se pudo iniciar sesión');await bootstrapPerson();setAuthenticated(true);setAuthOpen(false);setOtpSent(false)}catch(e){setError(e instanceof Error?e.message:'No se pudo verificar el código');setBusy(false);return}try{await hydrate()}catch{setError('Entraste, pero no pudimos recuperar tu información. Reintentá al abrir Mi Vida.')}const action=pendingAction;setPendingAction(null);try{if(action)await action()}catch(e){setError(e instanceof Error?e.message:'No pudimos continuar. Reintentá desde la pantalla actual.')}finally{setBusy(false)}}
 const submitMoment=async(expression=moment,destination:Scene='comprension')=>{
  setBusy(true);setError('');setClarification('')
  try{
   const s=await accompanyMoment(expression)
   if(!s.episode_id||!s.moment_id)throw new Error('Momento incompleto')
   if(s.safety?.state==='blocked'){go('momento');setClarification('Este momento necesita acompañamiento humano inmediato. Si hay peligro ahora, contactá los servicios de emergencia locales o a una persona de confianza. LUMEN no reemplaza esa ayuda.');return}
   setAdjustingReading(false);setEditingSelection(false);setFaroDraft(null);setFaro(expression.slice(0,280));setTrajectoryId(null);setMoment(expression);setUnderstanding(s.understanding||'¿Qué es lo que más te importa cuidar de lo que contaste? Podés escribirlo con tus palabras.')
   setInferredAreas(s.interpretation?.area_keys||[]);setMomentAreas(s.interpretation?.area_keys||[]);setNeedsContext(s.scene_id==='moment.clarify')
   setEpisodeId(s.episode_id);setMomentId(s.moment_id)
   setMomentExposedIds([]);setContextualPossibilities([]);setExcludedPossibilities([])
   setCompositionEntryId(null);setCompositionNotes([]);setConstellationIsFaro(false);setConstellationFromMoment(false);setContinuityMessage('')
   go(destination==='constelacion'?'comprension':destination)
  }catch(e){setError(e instanceof Error?e.message:'No pudimos procesar este momento')}finally{setBusy(false)}
 }
