 const confirmDraftAgreement=async(items:FaroPotential[],areas:string[],expected:Agreement|null)=>{
  if(!faro.trim()){setError('Escribí tu Faro en una frase.');return}
  setBusy(true);setError('')
  try {
   const saved=await confirmFaroReview(trajectoryId,faro.trim(),items,areas,expected?.version||0,expected?.faro_revision??null,momentId,faroReady==='yes'?'active':'paused',episodeId,understanding,draftConfirmRequest.current)
   if(saved.trajectory_id!==trajectoryId){setCompositionEntryId(null);setCompositionNotes([])}setFaroDraft(null);setTrajectoryId(saved.trajectory_id);setFaro(faro.trim());setEditingFaro(false)
   const verified=await getFaroAgreement(saved.trajectory_id)
   if(verified.version!==saved.agreement.version||verified.state!=='validated')throw new Error('No pudimos verificar el acuerdo guardado. Volvé a abrirlo antes de generar.')
   const reread=await getContinuitySnapshot();setFaros(reread.trajectories);setLifeMap(await getLifeMap())
   const result=await composeFaroConstellation(saved.trajectory_id,verified.version,availableTime)
   if(result.state==='agreement_required')throw new Error('El acuerdo cambió. Reabrilo y confirmalo antes de generar.')
   setContextualPossibilities(presentConstellation(result.items).slice(0,3));setFaroReservoir(presentConstellation(result.items));setConstellationIsFaro(true);setConstellationFromMoment(false);setEpisodeId(null);setMomentExposedIds([]);setExcludedPossibilities([]);setContinuityMessage(result.message||'');go('constelacion')
  }catch(e){setError(e instanceof Error?e.message:'No pudimos confirmar tu Faro. Lo escrito sigue acá.')}
  finally{setBusy(false)}
 }

 const ensureTrajectory=async()=>{if(trajectoryId)return trajectoryId;const t=momentId?await createTrajectoryFromMoment(faro,[],momentId):await createTrajectory(faro);setTrajectoryId(t.trajectory_id);return t.trajectory_id}
 const saveFaro=async()=>{if(!faro.trim()){setError('Escribí una orientación para guardar tu Faro.');return}setBusy(true);setError('');try{const id=await ensureTrajectory();await updateTrajectory(id,faro,faroReady==='yes'?'active':'paused');const snapshot=await getContinuitySnapshot();const saved=snapshot.trajectories.find(t=>t.trajectory_id===id);if(saved?.faro_text!==faro.trim())throw new Error('No pudimos verificar el Faro guardado');setFaros(snapshot.trajectories);setFaroHistory(saved.history||[]);setFaroStatus(saved.status);setLifeMap(await getLifeMap());setEditingFaro(false)}catch(e){setError(e instanceof Error?e.message:'No pudimos guardar tu Faro')}finally{setBusy(false)}}
 const changeFaro=async(status:'active'|'paused'|'closed')=>{if(!trajectoryId)return;setBusy(true);setError('');try{await updateTrajectory(trajectoryId,faro,status);const state=await getContinuitySnapshot();if(state.trajectories.find(t=>t.trajectory_id===trajectoryId)?.status!==status)throw new Error('No pudimos verificar el cambio');setFaroStatus(status);setLifeMap(await getLifeMap())}catch(e){setError(e instanceof Error?e.message:'No pudimos cambiar tu Faro')}finally{setBusy(false)}}
